  ('00000000-0000-4000-8000-001000000001', 'Rise and Reform', 'rise-and-reform', 'Small-group Reformer Pilates.', 'Small-group Reformer Pilates classes in Leamington Spa, Rugby, Stratford-upon-Avon and Kenilworth.', 'Reformer Pilates', array['Small-group Reformer Pilates classes']::text[], null, '/images/partners/rise-and-reform-logo.png', 'light', '/images/partners/rise-and-reform-cover.webp', null, null, false, false, 'https://risereformpilates.com/', '{}'::jsonb, 'Unit 13, Squab Hall Farm (Leamington studio)', 'Rise and Reform’s Leamington Spa studio is at Unit 13, Squab Hall Farm. It also has studios in Rugby, Stratford-upon-Avon and Kenilworth.', 'active', true, false, false),
  ('00000000-0000-4000-8000-001000000002', 'The Leamington Dog Field', 'the-leamington-dog-field', 'A bookable dog field at Squab Hall.', 'The Leamington Dog Field is based at Squab Hall. Sessions are booked online.', 'Dog field', array['Bookable field sessions']::text[], null, '/images/partners/leamington-dog-field-logo.png', 'light', null, null, null, false, false, 'https://leamingtonspadogfield.simplybook.it/', '{}'::jsonb, 'Squab Hall, Leamington Spa', null, 'active', true, false, false),
  ('00000000-0000-4000-8000-001000000003', 'Proper Golfing', 'proper-golfing', 'The Timeless Golf Swing, for golfers over 45.', 'Proper Golfing teaches the Timeless Golf Swing — effortless, repeatable golf coaching for golfers over 45 with PGA Professional Julian Mellor.', 'Golf coaching', array['Golf lessons for golfers over 45']::text[], null, '/images/partners/proper-golfing-logo.svg', 'light', '/images/partners/proper-golfing-studio.webp', null, null, false, false, 'https://propergolfing.com/', '{}'::jsonb, 'Unit 8, Squab Hall', null, 'active', true, false, false),
  ('00000000-0000-4000-8000-001000000004', 'Swim in a Tin', 'swim-in-a-tin', 'Swim at your own pace in a private space.', 'Swim at your own pace in a safe, private, personalised space to swim, train or learn — with or without qualified, supportive coaches.', 'Private swimming', array['Private swim sessions', 'Coached swimming']::text[], null, '/images/partners/swim-in-a-tin-logo.png', 'light', '/images/partners/swim-in-a-tin-containers.webp', null, null, false, false, 'https://www.swiminatin.com/', '{}'::jsonb, 'Squab Hall Farm', null, 'active', true, false, false),
  ('00000000-0000-4000-8000-001000000005', 'The Hide Cafe', 'the-hide-cafe', 'Tucked away. Worth finding.', 'A friendly independent café at Squab Hall Farm, serving freshly prepared breakfasts, lunches, homemade treats and great coffee in peaceful rural surroundings.', 'Café', array['Breakfast and lunch', 'Coffee, cakes and treats', 'Catering', 'The Hideaway private room']::text[], null, '/images/partners/the-hide-logo.png', 'light', '/images/partners/the-hide-cafe-cover.webp', 'thehide@squab.co.uk', '07939 411269', true, true, 'https://squabhallfarm.co.uk/services/cafe/', '{}'::jsonb, 'Squab Hall Farm, Harbury Lane, Leamington Spa', null, 'active', true, false, false),
  ('00000000-0000-4000-8000-001000000006', 'Project 23', 'project-23', 'Personal training in a private gym.', 'Personal training and small-group coaching at Project 23’s private gym in Leamington Spa, near Warwick.', 'Personal training', array['Personal training', 'Small-group coaching']::text[], null, '/images/partners/project-23-logo.png', 'dark', '/images/partners/project-23-coaching.webp', null, null, false, false, 'https://project23coaching.co.uk/', '{}'::jsonb, 'Squab Hall', null, 'active', true, false, false),
  ('00000000-0000-4000-8000-001000000007', 'AM Joinery', 'am-joinery', 'A joinery workshop based at Squab.', 'AM Joinery runs its joinery workshop from a unit at Squab.', 'Joinery', array['Joinery']::text[], null, null, 'light', '/images/partners/am-joinery-cover.webp', null, null, false, false, null, '{}'::jsonb, null, 'Squab tenant with a joinery workshop on site.', 'active', false, false, false),
  ('00000000-0000-4000-8000-001000000008', 'YouNeek Productions', 'youneek-productions', 'Video, photography and animation for brands.', 'YouNeek Productions creates video, photography and animation for brands, from its purpose-built production studio at Squab Hall Farm.', 'Video production', array['Video production', 'Photography', 'Animation', 'Studio hire']::text[], 'Winner of Videography Studio of the Year at the My Local Awards West Midlands 2026.', '/images/partners/youneek-productions-logo.png', 'light', '/images/partners/youneek-productions-cover.webp', null, null, false, false, 'https://www.youneekproductions.co.uk/', '{}'::jsonb, 'Unit 12, Squab Hall', null, 'active', false, false, false),
  ('00000000-0000-4000-8000-001000000009', 'Apex Connected', 'apex-connected', 'Managed print and document solutions.', 'Apex Connected delivers managed print services and document solutions that help businesses reduce costs, improve efficiency and take control of their printing.', 'Managed print services', array['Managed print services', 'Printers and copiers', 'Document solutions']::text[], null, '/images/partners/apex-connected-logo.png', 'light', null, null, null, false, false, 'https://www.apexconnected.com/', '{}'::jsonb, 'Squab Hall', null, 'active', false, false, false),
  ('00000000-0000-4000-8000-001000000010', 'Bio-Vent Systems', 'bio-vent-systems', 'Duct cleaning and grease management.', 'Bio-Vent Systems provides duct cleaning and grease management services. Its office is at Squab Hall.', 'Duct cleaning', array['Duct cleaning', 'Grease management']::text[], null, '/images/partners/bio-vent-systems-logo.png', 'light', null, null, null, false, false, 'https://bioventsystems.com/', '{}'::jsonb, 'Squab Hall', null, 'active', false, false, false),
  ('00000000-0000-4000-8000-001000000011', 'Young People First', 'young-people-first', 'Clubs, cafés and mentoring for young people.', 'Young People First (Midlands) is a charity working with disadvantaged young people aged 8–18 and their families in Leamington, through clubs, cafés and mentoring.', 'Youth charity', array['Youth clubs', 'Cafés', 'Mentoring']::text[], null, '/images/partners/young-people-first-logo.png', 'light', null, null, null, false, false, 'https://www.youngpeoplefirst.org.uk/', '{}'::jsonb, 'Container 10, Squab Hall', null, 'active', false, false, false),
  ('00000000-0000-4000-8000-001000000012', 'Squab Removals', 'squab-removals', 'Removals from the Squab Group.', 'Squab Removals is part of the Squab Group, providing removals from its base at Squab Hall.', 'Removals', array['Removals']::text[], null, '/images/partners/squab-removals-logo.png', 'light', null, null, null, false, false, 'https://squab.co.uk/', '{}'::jsonb, 'Squab Hall', null, 'active', false, false, false),
  ('00000000-0000-4000-8000-001000000014', 'GENEO Software', 'geneo-software', 'Software that enables organisations to work better.', 'GENEO builds lean management software that enables organisations to work better — trusted by industry leaders in the UK and around the world.', 'Software', array['Lean management software', 'Continuous improvement tools']::text[], null, '/images/partners/geneo-software-logo.png', 'light', null, null, null, false, false, 'https://www.geneo.co.uk/', '{}'::jsonb, 'Squab Hall', null, 'active', false, false, false),
  ('00000000-0000-4000-8000-001000000015', 'Peter Staunton Design', 'peter-staunton-design', 'Award-winning luxury interior design.', 'Peter Staunton Design Studio is an award-winning luxury interior designer, crafting bold, elegant homes in London, the Cotswolds and beyond.', 'Interior design', array['Interior architecture', 'Interior design']::text[], null, '/images/partners/peter-staunton-design-logo.png', 'light', '/images/partners/peter-staunton-design-cover.webp', null, null, false, false, 'https://peterstaunton.co.uk/', '{}'::jsonb, 'Squab Hall', null, 'active', false, false, false),
  ('00000000-0000-4000-8000-001000000016', 'Smart Image Furniture', 'smart-image-furniture', 'Office furniture, seating, refurbishment and maintenance.', 'A family-run Warwickshire business with over 50 years’ experience in office furniture and interiors — from furniture and seating to refurbishment, flooring, signage and maintenance.', 'Office furniture & interiors', array['Office furniture and seating', 'Refurbishment and maintenance', 'Carpets and flooring', 'Business signage']::text[], null, '/images/partners/smart-image-furniture-logo.png', 'light', null, null, null, false, false, 'https://www.smartimagefurniture.co.uk/', '{}'::jsonb, 'Squab Hall', null, 'active', false, false, false),
  ('00000000-0000-4000-8000-001000000017', 'The Warwickshire Gin Company', 'warwickshire-gin-company', 'Gins inspired by Warwickshire’s rich history.', 'Inspired by a rich history, The Warwickshire Gin Company’s gin collections infuse unique flavour combinations to represent the county’s own story — alongside gin tastings, cocktail evenings and afternoon G&Tea.', 'Craft gin distillery', array['Craft gin', 'Gin tastings', 'Cocktail evenings', 'Gifts']::text[], null, '/images/partners/warwickshire-gin-company-logo.png', 'light', '/images/partners/warwickshire-gin-company-cover.webp', null, null, false, false, 'https://warwickshiregincompany.co.uk/', '{}'::jsonb, 'Squab Hall', null, 'active', false, false, false),
